mapper.update:
merge into T_CX_PART_FINISH_QTY a USING (
select #{ITEM.statDate,jdbcType=DATE} stat_date, #{ITEM.embryoCode,jdbcType=VARCHAR} embryo_code, #{ITEM.finishQty,jdbcType=DOUBLE} finish_qty, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark, #{ITEM.bomDataVersion,jdbcType=VARCHAR} bom_data_version from dual
) b ON ( a.stat_date = b.stat_date and b.embryo_code = a.embryo_code and b.bom_data_version = a.bom_data_version AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.finish_qty = NVL(b.finish_qty, 0), a.update_by = b.create_by, a.update_time = sysdate WHEN NOT MATCHED THEN INSERT (a.id, a.stat_date, a.embryo_code, a.finish_qty, a.create_by, a.create_time, a.remark, a.del_flag, a.bom_data_version) values (SEQ_CX_FINISH_QTY.NEXTVAL, b.stat_date, b.embryo_code, NVL(b.finish_qty, 0), b.create_by, sysdate, b.remark, '0', b.bom_data_version)
